def gen(rng):
    def fmt(a, d):
        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + ' '.join(map(str, d))
    def rnd(n, hi, maxlen):
        a, d = [], []
        for _ in range(n):
            s = rng.randint(0, hi)
            e = min(hi, s + rng.randint(0, maxlen))
            a.append(s)
            d.append(e)
        return a, d
    tests = [fmt([5], [5]), fmt([0], [10 ** 9]), fmt([1, 1], [1, 1]), fmt([1, 5], [4, 9]), fmt([1, 5], [5, 9]),
             fmt([0, 0, 0, 0], [10 ** 9] * 4), fmt([1, 2, 3], [1, 2, 3]), fmt([1, 2, 3], [2, 3, 4])]
    for n in (2, 3, 4, 6, 8, 10, 15, 20):
        for hi, ml in ((10, 3), (40, 12)):
            tests.append(fmt(*rnd(n, hi, ml)))
    tests.append(fmt(*rnd(2000, 10 ** 9, 10 ** 7)))
    tests.append(fmt(*rnd(100000, 10 ** 9, 5 * 10 ** 5)))
    tests.append(fmt(*rnd(100000, 10 ** 9, 10 ** 9)))
    tests.append(fmt([10 * i for i in range(100000)], [10 * i + 10 for i in range(100000)]))
    tests.append(fmt([10 ** 8 + i for i in range(100000)], [9 * 10 ** 8 + i for i in range(100000)]))
    return tests
